-- Customer cohort retention percentages.
WITH x AS (SELECT customer_unique_id,date_trunc('month',order_purchase_timestamp)::date AS month_start,MIN(date_trunc('month',order_purchase_timestamp)::date) OVER(PARTITION BY customer_unique_id) AS cohort FROM analytics.v_order_value WHERE order_status='delivered'), a AS (SELECT cohort,month_start,COUNT(DISTINCT customer_unique_id) AS users FROM x GROUP BY 1,2) SELECT cohort,month_start,users,100.0*users/FIRST_VALUE(users) OVER(PARTITION BY cohort ORDER BY month_start) AS retention_pct FROM a;
